DROP FUNCTION IF EXISTS public.get_b2b_user_client_detail_secure(uuid);

CREATE OR REPLACE FUNCTION public.get_b2b_user_client_detail_secure(
  p_cliente_id uuid,
  p_scope text DEFAULT 'meus_produtores'
)
RETURNS TABLE(
  cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text,
  documento_mascarado text, telefone text, email text, cidade text, estado text,
  assignment_type text, can_create_simulation boolean, assigned_at timestamp with time zone
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_ok boolean := false;
  v_scope text := COALESCE(p_scope, 'meus_produtores');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;

  IF v_scope NOT IN ('meus_produtores','equipe','admin') THEN
    RAISE EXCEPTION 'invalid scope';
  END IF;

  IF has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN
    v_scope := 'meus_produtores';
    v_ok := EXISTS(SELECT 1 FROM public.partner_user_clients puc
                   WHERE puc.user_id = v_uid AND puc.cliente_id = p_cliente_id AND puc.active = true);
  ELSIF has_role(v_uid,'parceiro_b2b'::app_role) THEN
    v_partner := get_user_partner_id();
    IF v_scope = 'meus_produtores' THEN
      v_ok := EXISTS(SELECT 1 FROM public.partner_user_clients puc
                     WHERE puc.user_id = v_uid
                       AND puc.cliente_id = p_cliente_id
                       AND puc.partner_id = v_partner
                       AND puc.active = true);
    ELSIF v_scope = 'equipe' THEN
      v_ok := EXISTS(SELECT 1 FROM public.partner_clients pc
                     WHERE pc.partner_id = v_partner AND pc.cliente_id = p_cliente_id AND pc.active = true);
    END IF;
  ELSIF has_role(v_uid,'administrador'::app_role) OR has_role(v_uid,'gestor_comercial'::app_role) THEN
    IF v_scope IN ('admin','equipe') THEN
      v_ok := true;
    END IF;
  END IF;

  IF NOT v_ok THEN RAISE EXCEPTION 'access denied'; END IF;

  RETURN QUERY
  SELECT c.id, c.nome, c.razao_social, c.nome_fantasia, c.tipo_pessoa,
    CASE WHEN c.cpf_cnpj IS NULL THEN NULL
         ELSE repeat('*', greatest(length(c.cpf_cnpj)-4,0)) || right(c.cpf_cnpj,4)
    END,
    c.telefone, c.email,
    c.endereco_municipio, c.endereco_estado,
    (SELECT assignment_type FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1),
    (SELECT can_create_simulation FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1),
    (SELECT assigned_at FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1)
  FROM public.clientes c
  WHERE c.id = p_cliente_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_b2b_user_client_detail_secure(uuid, text) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_b2b_user_clients_secure(p_user_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text)
 RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text, documento_mascarado text, telefone text, cidade text, estado text, assignment_type text, can_create_simulation boolean, can_monitor boolean, assigned_at timestamp with time zone, ultima_simulacao_at timestamp with time zone, total_simulacoes bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_target uuid;
  v_partner uuid;
  v_is_tec boolean := has_role(v_uid, 'parceiro_b2b_tecnico'::app_role);
  v_is_gest boolean := has_role(v_uid, 'parceiro_b2b'::app_role);
  v_is_admin boolean := has_role(v_uid, 'administrador'::app_role) OR has_role(v_uid, 'gestor_comercial'::app_role);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF NOT (v_is_tec OR v_is_gest OR v_is_admin) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  IF v_is_tec THEN
    v_target := v_uid;
  ELSIF v_is_gest THEN
    v_target := COALESCE(p_user_id, v_uid);
    v_partner := get_user_partner_id();
    IF v_target <> v_uid THEN
      IF NOT EXISTS (SELECT 1 FROM public.partner_users pu WHERE pu.user_id = v_target AND pu.partner_id = v_partner) THEN
        RAISE EXCEPTION 'usuario nao pertence ao mesmo parceiro';
      END IF;
    END IF;
  ELSE
    v_target := p_user_id;
  END IF;

  RETURN QUERY
  SELECT
    c.id AS cliente_id,
    c.nome, c.razao_social, c.nome_fantasia, c.tipo_pessoa,
    CASE
      WHEN c.cpf_cnpj IS NULL THEN NULL
      WHEN length(c.cpf_cnpj) >= 4 THEN repeat('*', greatest(length(c.cpf_cnpj)-4,0)) || right(c.cpf_cnpj,4)
      ELSE '****'
    END AS documento_mascarado,
    c.telefone,
    c.endereco_municipio AS cidade,
    c.endereco_estado AS estado,
    puc.assignment_type,
    puc.can_create_simulation,
    puc.can_monitor,
    puc.assigned_at,
    (SELECT max(ps.created_at) FROM public.partner_simulations ps
       WHERE ps.cliente_id = c.id
         AND ps.partner_id = puc.partner_id
         AND (
           v_is_tec = true AND ps.created_by = v_uid
           OR v_is_gest = true AND ps.created_by = v_target
           OR v_is_admin = true AND (v_target IS NULL OR ps.created_by = v_target)
         )
    ) AS ultima_simulacao_at,
    (SELECT count(*) FROM public.partner_simulations ps
       WHERE ps.cliente_id = c.id
         AND ps.partner_id = puc.partner_id
         AND (
           v_is_tec = true AND ps.created_by = v_uid
           OR v_is_gest = true AND ps.created_by = v_target
           OR v_is_admin = true AND (v_target IS NULL OR ps.created_by = v_target)
         )
    ) AS total_simulacoes
  FROM public.partner_user_clients puc
  JOIN public.clientes c ON c.id = puc.cliente_id
  WHERE puc.active = true
    AND (v_target IS NULL OR puc.user_id = v_target)
    AND (p_search IS NULL OR p_search = '' OR
         coalesce(c.nome,'') ILIKE '%'||p_search||'%' OR
         coalesce(c.razao_social,'') ILIKE '%'||p_search||'%' OR
         coalesce(c.nome_fantasia,'') ILIKE '%'||p_search||'%' OR
         coalesce(c.endereco_municipio,'') ILIKE '%'||p_search||'%');
END;
$function$;

-- 1) Internal helper (not callable from PostgREST — no EXECUTE to authenticated)
CREATE OR REPLACE FUNCTION public.insert_partner_catalog_access_log_internal(
  p_action text,
  p_partner_id uuid,
  p_user_id uuid,
  p_cliente_id uuid DEFAULT NULL,
  p_simulation_id uuid DEFAULT NULL,
  p_order_id uuid DEFAULT NULL,
  p_target_user_id uuid DEFAULT NULL,
  p_details jsonb DEFAULT '{}'::jsonb
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_id uuid;
  v_allowed text[] := ARRAY[
    'b2b_user_client_assigned','b2b_user_client_unassigned','producer_view',
    'catalog_view','item_view','ficha_view','ficha_download',
    'simulation_created','simulation_sent_to_manager','simulation_archived',
    'simulation_converted_to_order'
  ];
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'user_id obrigatório'; END IF;
  IF NOT (p_action = ANY(v_allowed)) THEN
    RAISE EXCEPTION 'action inválida: %', p_action;
  END IF;
  SELECT role::text INTO v_role FROM public.user_roles WHERE user_id = p_user_id LIMIT 1;
  INSERT INTO public.partner_catalog_access_logs
    (user_id, role, action, partner_id, cliente_id, simulation_id, order_id, target_user_id, details)
  VALUES
    (p_user_id, v_role, p_action, p_partner_id, p_cliente_id, p_simulation_id, p_order_id, p_target_user_id, COALESCE(p_details,'{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;

REVOKE ALL ON FUNCTION public.insert_partner_catalog_access_log_internal(text, uuid, uuid, uuid, uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;

-- 2) Add SELECT policy for técnico B2B viewing own logs
DROP POLICY IF EXISTS pcal_select_tecnico_own ON public.partner_catalog_access_logs;
CREATE POLICY pcal_select_tecnico_own ON public.partner_catalog_access_logs
  FOR SELECT TO authenticated
  USING (has_role(auth.uid(),'parceiro_b2b_tecnico'::app_role) AND user_id = auth.uid());

-- 3) send/archive/convert also record in partner_catalog_access_logs
CREATE OR REPLACE FUNCTION public.send_partner_simulation_to_manager_secure(p_simulation_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Simulação não encontrada'; END IF;
  IF v_sim.status <> 'rascunho' THEN RAISE EXCEPTION 'Somente simulações em rascunho podem ser enviadas'; END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND (v_sim.created_by = v_uid OR v_sim.partner_id = v_partner_id) THEN v_allowed := true;
  END IF;
  IF NOT v_allowed THEN RAISE EXCEPTION 'Sem permissão para enviar esta simulação'; END IF;

  UPDATE partner_simulations SET status = 'enviada_gestor', updated_at = now() WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_sim.partner_id, v_uid, 'simulation_sent_to_manager',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'enviada_gestor'));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_sent_to_manager', v_sim.partner_id, v_uid,
    v_sim.cliente_id, p_simulation_id, NULL, NULL, '{}'::jsonb);
END;
$$;

CREATE OR REPLACE FUNCTION public.archive_partner_simulation_secure(p_simulation_id uuid, p_reason text DEFAULT NULL)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Simulação não encontrada'; END IF;
  IF v_sim.status = 'convertida_pedido' THEN RAISE EXCEPTION 'Simulação já convertida em pedido não pode ser arquivada'; END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND v_sim.partner_id = v_partner_id THEN v_allowed := true;
  END IF;
  IF NOT v_allowed THEN RAISE EXCEPTION 'Sem permissão para arquivar esta simulação'; END IF;

  UPDATE partner_simulations SET status = 'arquivada', updated_at = now() WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_sim.partner_id, v_uid, 'simulation_archived',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'arquivada', 'reason', p_reason));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_archived', v_sim.partner_id, v_uid,
    v_sim.cliente_id, p_simulation_id, NULL, NULL,
    jsonb_build_object('reason', p_reason));
END;
$$;

CREATE OR REPLACE FUNCTION public.assign_b2b_user_client_secure(p_user_id uuid, p_cliente_id uuid, p_assignment_type text DEFAULT 'monitoramento'::text, p_can_create_simulation boolean DEFAULT true, p_can_monitor boolean DEFAULT true, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_id uuid;
  v_is_gest boolean := has_role(v_uid, 'parceiro_b2b'::app_role);
  v_is_admin boolean := has_role(v_uid, 'administrador'::app_role) OR has_role(v_uid, 'gestor_comercial'::app_role);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN RAISE EXCEPTION 'access denied'; END IF;
  IF NOT (v_is_gest OR v_is_admin) THEN RAISE EXCEPTION 'access denied'; END IF;

  IF v_is_gest AND NOT v_is_admin THEN
    v_partner := get_user_partner_id();
  ELSE
    SELECT partner_id INTO v_partner FROM public.partner_users WHERE user_id = p_user_id LIMIT 1;
  END IF;

  IF v_partner IS NULL THEN RAISE EXCEPTION 'partner nao identificado'; END IF;

  IF v_is_admin THEN
    INSERT INTO public.partner_clients (partner_id, cliente_id, assigned_by, active)
    VALUES (v_partner, p_cliente_id, v_uid, true)
    ON CONFLICT (partner_id, cliente_id) DO UPDATE SET active = true, updated_at = now();
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.partner_clients
      WHERE partner_id = v_partner AND cliente_id = p_cliente_id AND active = true
    ) THEN
      RAISE EXCEPTION 'Cliente não está liberado para este parceiro. Solicite ao administrador AR Bio.';
    END IF;
  END IF;

  INSERT INTO public.partner_user_clients
    (partner_id, user_id, cliente_id, assignment_type, can_create_simulation, can_monitor, notes, assigned_by, active)
  VALUES
    (v_partner, p_user_id, p_cliente_id, p_assignment_type, p_can_create_simulation, p_can_monitor, p_notes, v_uid, true)
  ON CONFLICT (partner_id, user_id, cliente_id) DO UPDATE
    SET assignment_type = EXCLUDED.assignment_type,
        can_create_simulation = EXCLUDED.can_create_simulation,
        can_monitor = EXCLUDED.can_monitor,
        notes = EXCLUDED.notes,
        active = true,
        updated_at = now()
  RETURNING id INTO v_id;

  PERFORM public.insert_partner_catalog_access_log_internal(
    'b2b_user_client_assigned',
    v_partner,
    v_uid,
    p_cliente_id,
    NULL,
    NULL,
    p_user_id,
    jsonb_build_object(
      'assignment_type', p_assignment_type,
      'can_create_simulation', p_can_create_simulation,
      'can_monitor', p_can_monitor
    )
  );

  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.unassign_b2b_user_client_secure(p_user_id uuid, p_cliente_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN RAISE EXCEPTION 'access denied'; END IF;

  IF has_role(v_uid,'parceiro_b2b'::app_role) THEN
    v_partner := get_user_partner_id();
  ELSIF has_role(v_uid,'administrador'::app_role) OR has_role(v_uid,'gestor_comercial'::app_role) THEN
    SELECT partner_id INTO v_partner FROM public.partner_user_clients
      WHERE user_id = p_user_id AND cliente_id = p_cliente_id LIMIT 1;
  ELSE
    RAISE EXCEPTION 'access denied';
  END IF;

  UPDATE public.partner_user_clients
     SET active = false, updated_at = now()
   WHERE user_id = p_user_id AND cliente_id = p_cliente_id
     AND (v_partner IS NULL OR partner_id = v_partner);

  UPDATE public.partner_technician_clients
     SET active = false, updated_at = now()
   WHERE technician_user_id = p_user_id AND cliente_id = p_cliente_id
     AND (v_partner IS NULL OR partner_id = v_partner);

  PERFORM public.insert_partner_catalog_access_log_internal(
    'b2b_user_client_unassigned',
    v_partner,
    v_uid,
    p_cliente_id,
    NULL,
    NULL,
    p_user_id,
    jsonb_build_object('reason', p_reason)
  );

  RETURN true;
END;
$function$;

-- convert_partner_simulation_to_order_secure: append B2B log at the end
CREATE OR REPLACE FUNCTION public.log_simulation_converted_to_order(p_partner uuid, p_uid uuid, p_cliente uuid, p_simulation uuid, p_order uuid, p_details jsonb)
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  SELECT public.insert_partner_catalog_access_log_internal(
    'simulation_converted_to_order', p_partner, p_uid, p_cliente, p_simulation, p_order, NULL, p_details
  );
  SELECT NULL::void;
$$;
REVOKE ALL ON FUNCTION public.log_simulation_converted_to_order(uuid, uuid, uuid, uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.convert_partner_simulation_to_order_secure(p_simulation_id uuid, p_observacoes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_partner_b2b boolean;
  v_is_tecnico boolean;
  v_user_partner uuid;
  v_sim record;
  v_partner_id uuid;
  v_partner_desconto numeric(5,2);
  v_order_id uuid;
  v_numero text;
  v_item record;
  v_prod_row record;
  v_micro_row record;
  v_price record;
  v_nome text;
  v_codigo text;
  v_base numeric(12,2);
  v_dose_base numeric(12,2);
  v_preco_tabela numeric(12,2);
  v_desc numeric(5,2);
  v_preco_final numeric(12,2);
  v_line_subtotal numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_total numeric(12,2) := 0;
  v_desconto_total numeric(12,2) := 0;
  v_items_count int := 0;
  v_qty numeric(12,2);
  v_unidade text := 'hectare';
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;

  v_is_admin := has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial');
  v_is_partner_b2b := has_role(v_uid, 'parceiro_b2b');
  v_is_tecnico := has_role(v_uid, 'parceiro_b2b_tecnico');

  IF v_is_tecnico AND NOT v_is_admin AND NOT v_is_partner_b2b THEN
    RAISE EXCEPTION 'forbidden_role_tecnico_cannot_convert';
  END IF;
  IF NOT (v_is_admin OR v_is_partner_b2b) THEN
    RAISE EXCEPTION 'forbidden_role';
  END IF;

  SELECT * INTO v_sim FROM public.partner_simulations WHERE id = p_simulation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'simulation_not_found'; END IF;
  IF v_sim.status = 'convertida_pedido' THEN RAISE EXCEPTION 'already_converted'; END IF;
  IF v_sim.status NOT IN ('rascunho','enviada_gestor') THEN RAISE EXCEPTION 'invalid_status'; END IF;

  v_partner_id := v_sim.partner_id;
  IF v_is_partner_b2b AND NOT v_is_admin THEN
    v_user_partner := get_user_partner_id();
    IF v_user_partner IS NULL OR v_user_partner <> v_partner_id THEN
      RAISE EXCEPTION 'forbidden_partner';
    END IF;
  END IF;

  SELECT COALESCE(desconto_padrao_percentual, 0) INTO v_partner_desconto
    FROM public.partner_accounts WHERE id = v_partner_id;

  v_numero := 'PB2B-' || to_char(now(),'YYYYMMDDHH24MISS') || '-' || substr(v_partner_id::text,1,4);

  INSERT INTO public.partner_orders(
    partner_id, cliente_id, numero, status, tipo_origem, origem_simulacao_id,
    subtotal, desconto_total, total, observacoes, created_by
  ) VALUES (
    v_partner_id, v_sim.cliente_id, v_numero, 'em_analise', 'simulacao', p_simulation_id,
    0, 0, 0, COALESCE(p_observacoes, v_sim.observacoes), v_uid
  ) RETURNING id INTO v_order_id;

  FOR v_item IN SELECT * FROM public.partner_simulation_items WHERE simulation_id = p_simulation_id LOOP
    v_qty := v_item.quantidade;
    IF v_qty <= 0 THEN RAISE EXCEPTION 'invalid_qty'; END IF;
    v_base := NULL; v_dose_base := NULL; v_price := NULL;

    IF v_item.item_tipo = 'produto' THEN
      SELECT id, nome, codigo, valor_ha_brl, valor_dose_brl, valor_litro_brl, dose_ml_ha,
             ativo, COALESCE(b2b_enabled, true) AS b2b_enabled
        INTO v_prod_row FROM public.produtos WHERE id = v_item.item_id;
      IF NOT FOUND OR v_prod_row.ativo = false OR v_prod_row.b2b_enabled = false THEN
        RAISE EXCEPTION 'product_unavailable';
      END IF;
      v_nome := v_prod_row.nome; v_codigo := v_prod_row.codigo;
      v_dose_base := COALESCE(NULLIF(v_prod_row.valor_dose_brl,0), NULLIF(v_prod_row.valor_litro_brl,0)/10.0);
      v_base := COALESCE(NULLIF(v_prod_row.valor_ha_brl,0),
        CASE WHEN v_prod_row.dose_ml_ha IS NOT NULL AND v_prod_row.dose_ml_ha > 0
             THEN (v_prod_row.dose_ml_ha/100.0) * v_dose_base END);
      SELECT preco_tabela, desconto_percentual, preco_final INTO v_price
        FROM public.partner_product_prices
        WHERE partner_id = v_partner_id AND product_id = v_item.item_id AND ativo = true;
    ELSIF v_item.item_tipo = 'microrganismo' THEN
      SELECT id, nome, codigo, valor_dose_brl, valor_litro_brl, dose_ml_ha,
             ativo, COALESCE(b2b_enabled, false) AS b2b_enabled
        INTO v_micro_row FROM public.microrganismos WHERE id = v_item.item_id;
      IF NOT FOUND OR v_micro_row.ativo = false OR v_micro_row.b2b_enabled = false THEN
        RAISE EXCEPTION 'product_unavailable';
      END IF;
      v_nome := v_micro_row.nome; v_codigo := v_micro_row.codigo;
      v_dose_base := COALESCE(NULLIF(v_micro_row.valor_dose_brl,0), NULLIF(v_micro_row.valor_litro_brl,0)/10.0);
      v_base := CASE WHEN v_micro_row.dose_ml_ha IS NOT NULL AND v_micro_row.dose_ml_ha > 0
                     THEN (v_micro_row.dose_ml_ha/100.0) * v_dose_base END;
      SELECT preco_tabela, desconto_percentual, preco_final INTO v_price
        FROM public.partner_product_prices
        WHERE partner_id = v_partner_id AND microrganismo_id = v_item.item_id AND ativo = true;
    ELSE
      RAISE EXCEPTION 'invalid_item_tipo';
    END IF;

    IF v_price.preco_tabela IS NOT NULL THEN
      v_preco_tabela := v_price.preco_tabela;
      v_desc := COALESCE(v_price.desconto_percentual, 0);
      v_preco_final := COALESCE(v_price.preco_final, ROUND(v_preco_tabela * (1 - v_desc/100.0), 2));
    ELSE
      IF v_base IS NULL OR v_base <= 0 THEN RAISE EXCEPTION 'price_unavailable'; END IF;
      v_preco_tabela := ROUND(v_base, 2);
      v_desc := COALESCE(v_partner_desconto, 0);
      v_preco_final := ROUND(v_preco_tabela * (1 - v_desc/100.0), 2);
    END IF;
    IF v_preco_final IS NULL OR v_preco_final <= 0 THEN RAISE EXCEPTION 'price_unavailable'; END IF;

    v_line_subtotal := ROUND(v_preco_final * v_qty, 2);
    v_subtotal := v_subtotal + ROUND(v_preco_tabela * v_qty, 2);
    v_total := v_total + v_line_subtotal;

    INSERT INTO public.partner_order_items(
      order_id, product_id, microrganismo_id, quantidade, preco_unitario,
      desconto_percentual, subtotal, unidade_medida,
      produto_nome_snapshot, produto_codigo_snapshot,
      preco_tabela_snapshot, desconto_percentual_snapshot, preco_unitario_final_snapshot
    ) VALUES (
      v_order_id,
      CASE WHEN v_item.item_tipo = 'produto' THEN v_item.item_id END,
      CASE WHEN v_item.item_tipo = 'microrganismo' THEN v_item.item_id END,
      v_qty, v_preco_final, v_desc, v_line_subtotal, v_unidade,
      COALESCE(v_nome, v_item.nome), v_codigo,
      v_preco_tabela, v_desc, v_preco_final
    );
    v_items_count := v_items_count + 1;
  END LOOP;

  IF v_items_count = 0 THEN RAISE EXCEPTION 'empty_simulation'; END IF;
  v_desconto_total := v_subtotal - v_total;

  UPDATE public.partner_orders
     SET subtotal = v_subtotal, desconto_total = v_desconto_total, total = v_total
   WHERE id = v_order_id;

  UPDATE public.partner_simulations
     SET status = 'convertida_pedido', converted_order_id = v_order_id,
         converted_by = v_uid, converted_at = now(), updated_at = now()
   WHERE id = p_simulation_id;

  INSERT INTO public.partner_order_audit_logs(
    order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos
  ) VALUES (
    v_order_id, v_partner_id, v_uid, 'converted_from_simulation', NULL,
    jsonb_build_object(
      'simulation_id', p_simulation_id,
      'cliente_id', v_sim.cliente_id,
      'subtotal', v_subtotal,
      'desconto_total', v_desconto_total,
      'total', v_total,
      'items_count', v_items_count
    )
  );

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_converted_to_order',
    v_partner_id,
    v_uid,
    v_sim.cliente_id,
    p_simulation_id,
    v_order_id,
    NULL,
    jsonb_build_object(
      'subtotal', v_subtotal,
      'desconto_total', v_desconto_total,
      'total', v_total,
      'items_count', v_items_count
    )
  );

  RETURN v_order_id;
END;
$function$;

DROP FUNCTION IF EXISTS public.log_simulation_converted_to_order(uuid, uuid, uuid, uuid, uuid, jsonb);

CREATE OR REPLACE FUNCTION public.get_portal_cliente_b2b_order_detail_secure(p_order_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_order public.partner_orders%ROWTYPE;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;

  IF v_order.cliente_id IS NULL
     OR NOT public._portal_cliente_user_has_link(auth.uid(), v_order.cliente_id) THEN
    RAISE EXCEPTION 'forbidden_cliente_vinculo';
  END IF;

  SELECT jsonb_build_object(
    'header', jsonb_build_object(
      'id', v_order.id,
      'numero', v_order.numero,
      'status', v_order.status,
      'created_at', v_order.created_at,
      'requested_delivery_date', v_order.requested_delivery_date,
      'estimated_delivery_date', v_order.estimated_delivery_date,
      'approved_at', v_order.approved_at,
      'partner_id', v_order.partner_id,
      'partner_nome', COALESCE(pa.nome_fantasia, pa.razao_social),
      'total', v_order.total,
      'origin_simulation_id', v_order.origin_simulation_id,
      'cultura', v_order.cultura,
      'area_total_ha', v_order.area_total_ha
    ),
    'items', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', it.id,
        'nome', COALESCE(it.produto_nome_snapshot, p.nome, m.nome),
        'codigo', COALESCE(it.produto_codigo_snapshot, p.codigo, m.codigo),
        'quantidade', it.quantidade,
        'unidade_medida', it.unidade_medida,
        'preco_unitario', it.preco_unitario,
        'subtotal', it.subtotal
      ) ORDER BY it.created_at)
      FROM public.partner_order_items it
      LEFT JOIN public.produtos p ON p.id = it.produto_id
      LEFT JOIN public.microrganismos m ON m.id = it.microrganismo_id
      WHERE it.order_id = v_order.id
    ), '[]'::jsonb)
  ) INTO v_result
  FROM public.partner_accounts pa
  WHERE pa.id = v_order.partner_id;

  RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_portal_cliente_b2b_simulation_detail_secure(p_simulation_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_sim public.partner_simulations%ROWTYPE;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT * INTO v_sim FROM public.partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;

  IF v_sim.cliente_id IS NULL
     OR NOT public._portal_cliente_user_has_link(auth.uid(), v_sim.cliente_id) THEN
    RAISE EXCEPTION 'forbidden_cliente_vinculo';
  END IF;

  IF v_sim.status::text NOT IN ('enviada_gestor', 'convertida_pedido') THEN
    RAISE EXCEPTION 'simulation_not_visible';
  END IF;

  SELECT jsonb_build_object(
    'header', jsonb_build_object(
      'id', v_sim.id,
      'titulo', v_sim.titulo,
      'status', v_sim.status,
      'total_cheio', v_sim.total_cheio,
      'created_at', v_sim.created_at,
      'updated_at', v_sim.updated_at,
      'converted_order_id', v_sim.converted_order_id,
      'partner_id', v_sim.partner_id,
      'partner_nome', COALESCE(pa.nome_fantasia, pa.razao_social),
      'cultura', v_sim.cultura,
      'area_total_ha', v_sim.area_total_ha,
      'objetivo_tecnico', v_sim.objetivo_tecnico
    ),
    'items', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', si.id,
        'nome', si.nome,
        'item_tipo', si.item_tipo,
        'quantidade', si.quantidade,
        'valor_unitario_cheio', si.valor_unitario_cheio,
        'subtotal', si.subtotal
      ) ORDER BY si.created_at)
      FROM public.partner_simulation_items si
      WHERE si.simulation_id = v_sim.id
    ), '[]'::jsonb)
  ) INTO v_result
  FROM public.partner_accounts pa
  WHERE pa.id = v_sim.partner_id;

  RETURN v_result;
END;
$$;

